question.answer:
from math import gcd
import random

def order(a, N):
    r, x = 1, a % N
    while x != 1:
        x = (x * a) % N
        r += 1
    return r

def factors_from_order(a, r, N):
    if r % 2 != 0:
        return None
    h = pow(a, r // 2, N)
    if h == N - 1:
        return None
    f = tuple(sorted({gcd(h - 1, N), gcd(h + 1, N)} - {1, N}))
    if len(f) != 2:
        cand = [d for d in (gcd(h - 1, N), gcd(h + 1, N)) if 1 < d < N]
        if not cand:
            return None
        d = cand[0]
        return tuple(sorted((d, N // d)))
    return f

def shor_classical(N, seed):
    rng = random.Random(seed)
    while True:
        a = rng.randrange(2, N)
        g = gcd(a, N)
        if g > 1:
            return tuple(sorted((g, N // g)))
        f = factors_from_order(a, order(a, N), N)
        if f:
            return f

